'use strict';

// VARIABLES //

var RE_PROSE_START = /^[a-zA-Z`(*'"[\u0080-￿]/;
var RE_NUMBERED = /^\d+\. /;


// MAIN //

/**
* Collapses continuation lines within prose paragraphs while preserving blank lines, sub-indented content, list items, and table rows.
*
* @private
* @param {string} text - text with indent already stripped
* @returns {string} text with continuation lines joined
*/
function collapseContinuations( text ) {
	var current;
	var parts;
	var lines;
	var line;
	var i;

	lines = text.split( '\n' );
	parts = [];
	current = [];
	for ( i = 0; i < lines.length; i++ ) {
		line = lines[ i ];
		if (
			line.length > 0 &&
			RE_PROSE_START.test( line ) &&
			!RE_NUMBERED.test( line )
		) {
			current.push( line );
		} else {
			if ( current.length > 0 ) {
				parts.push( current.join( ' ' ) );
				current = [];
			}
			parts.push( line );
		}
	}
	if ( current.length > 0 ) {
		parts.push( current.join( ' ' ) );
	}
	return parts.join( '\n' );
}


// EXPORTS //

module.exports = collapseContinuations;
